std::string real(double value, int digits) {
    const double scale = std::pow(10.0, digits);
    if (std::abs(value) < 0.5 / scale)
        value = 0;
    std::ostringstream output;
    output << std::fixed << std::setprecision(digits) << value;
    return output.str();
}
